"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogTitle } from "@/components/ui/dialog";
import { useAddItems } from "@/features/catalog/api/books.api";
import { addItemsSchema, type AddItemsInput, type AddItemsValues } from "@/features/catalog/schemas/book.schema";
import { applyServerErrors } from "@/lib/form";
import { COPIES_DEFAULTS, CopiesFields } from "./copies-fields";

// FE-4.3.10. Barcodes are generated by the backend (PST-YYYY-seq6).
export function AddItemsDialog({ bookId, open, onClose }: { bookId: string; open: boolean; onClose: () => void }) {
  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
      <DialogContent>{open ? <AddItemsForm bookId={bookId} onDone={onClose} /> : null}</DialogContent>
    </Dialog>
  );
}

function AddItemsForm({ bookId, onDone }: { bookId: string; onDone: () => void }) {
  const add = useAddItems(bookId);
  const {
    register,
    handleSubmit,
    setError,
    formState: { errors },
  } = useForm<AddItemsInput, unknown, AddItemsValues>({ resolver: zodResolver(addItemsSchema), defaultValues: COPIES_DEFAULTS });

  return (
    <form
      className="flex flex-col gap-4"
      onSubmit={handleSubmit((v) => add.mutate(v, { onSuccess: onDone, onError: (e) => applyServerErrors(e, setError) }))}
    >
      <div className="flex flex-col gap-1">
        <DialogTitle>Tambah eksemplar</DialogTitle>
        <DialogDescription>Barcode dibuat otomatis dan aktif begitu disimpan.</DialogDescription>
      </div>
      <CopiesFields p={register} errors={errors} idPrefix="add-" />
      {errors.root?.server ? (
        <p role="alert" className="text-body-sm text-primary-container dark:text-primary">
          {errors.root.server.message}
        </p>
      ) : null}
      <div className="flex justify-end gap-2">
        <Button type="button" variant="secondary" onClick={onDone}>
          Batal
        </Button>
        <Button type="submit" loading={add.isPending}>
          Tambah
        </Button>
      </div>
    </form>
  );
}
